const STARTER_TASK_TEXTS=new Set(["Solve FR consolidation practice set","Revise Audit professional ethics","Attempt one IBS case study"]);
const seed={progress:{},topicChecks:{},customTopics:{},topicActivity:{},tasks:[],roadmapChecks:{},checks:{}};
let state=loadState(),tab="Home",paper="FR",timer=0,timerId=null;
state.topicActivity=state.topicActivity||{};state.customTopics=state.customTopics||{};state.tasks=(state.tasks||[]).filter(task=>!STARTER_TASK_TEXTS.has(task.text));
const view=document.querySelector("#view"),title=document.querySelector("#page-title"),subtitle=document.querySelector("#page-subtitle");
const navItems={Home:"⌂","Study Plan":"▤",Tasks:"✓",Roadmap:"◇"};
function applyTheme(theme){const dark=theme==="dark";document.documentElement.dataset.theme=dark?"dark":"light";try{localStorage.setItem("sweety-theme",dark?"dark":"light")}catch{}const button=document.querySelector("#theme-toggle");if(button){button.setAttribute("aria-pressed",String(dark));button.setAttribute("aria-label",dark?"Enable light theme":"Enable dark theme");button.querySelector("span").textContent=dark?"☀":"☾";button.querySelector("b").textContent=dark?"Light":"Dark"}document.querySelector('meta[name="theme-color"]')?.setAttribute("content",dark?"#080d12":"#f3f7f2")}
document.querySelector("#theme-toggle")?.addEventListener("click",()=>applyTheme(document.documentElement.dataset.theme==="dark"?"light":"dark"));applyTheme(document.documentElement.dataset.theme);

function freshState(){return JSON.parse(JSON.stringify(seed))}
function loadState(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||freshState()}catch{return freshState()}}
function rebuildTopicActivity(){const activity={};Object.values(state.topicChecks||{}).forEach(checks=>Object.values(checks||{}).forEach(item=>{if(item?.done&&item.completedAt)activity[item.completedAt]=(activity[item.completedAt]||0)+1}));Object.values(state.customTopics||{}).forEach(topics=>(topics||[]).forEach(item=>{if(item.done&&item.completedAt)activity[item.completedAt]=(activity[item.completedAt]||0)+1}));state.topicActivity=activity}
function completedTopicsOn(day=dateKey()){let count=0;Object.values(state.topicChecks||{}).forEach(checks=>Object.values(checks||{}).forEach(item=>{if(item?.done&&item.completedAt===day)count++}));Object.values(state.customTopics||{}).forEach(topics=>(topics||[]).forEach(item=>{if(item?.done&&item.completedAt===day)count++}));return count}
function saveState(){rebuildTopicActivity();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));updateTopStats();window.cloudSync?.schedule(state)}
function esc(value=""){return String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function safeNote(html=""){const doc=new DOMParser().parseFromString(`<div>${html}</div>`,"text/html"),root=doc.body.firstElementChild,allowed=new Set(["DIV","P","BR","B","STRONG","I","EM","U","MARK","H3","UL","OL","LI","A","SPAN"]);root?.querySelectorAll("*").forEach(el=>{if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);return}[...el.attributes].forEach(a=>{if(!(el.tagName==="A"&&a.name==="href")&&!(el.tagName==="SPAN"&&a.name==="data-check"))el.removeAttribute(a.name)});if(el.tagName==="A"&&!/^https?:\/\//i.test(el.getAttribute("href")||""))el.removeAttribute("href")});return root?.innerHTML||""}
function progressKey(code,index){return `${code}-${index}`}
function allChapters(){return subjects.flatMap(s=>s.chapters.map((chapter,index)=>({s,chapter,index,key:progressKey(s.code,index)})))}
function toast(message){const el=document.createElement("div");el.className="toast";el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2500)}
