function dateKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`}
function setProgress(key,patch){const previous=state.progress[key]||{};state.topicActivity=state.topicActivity||{};if(Object.prototype.hasOwnProperty.call(patch,"done")&&patch.done!==previous.done){if(patch.done){const day=dateKey();patch.completedAt=day;state.topicActivity[day]=(state.topicActivity[day]||0)+1}else if(previous.completedAt){state.topicActivity[previous.completedAt]=Math.max(0,(state.topicActivity[previous.completedAt]||0)-1);patch.completedAt=""}}state.progress[key]={...previous,...patch};saveState()}
function setupNav(){document.querySelector("#nav").innerHTML=Object.entries(navItems).map(([name,icon])=>`<button class="nav-btn ${name===tab?"active":""}" data-tab="${name}"><span>${icon}</span>${name}</button>`).join("");document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()})}
function render(){if(tab==="Today")tab="Home";if(tab==="Syllabus")tab="Study Plan";setupNav();updateTopStats();title.innerHTML=`${tab==="Home"?"Good afternoon, Sweety":tab} <em>✦</em>`;subtitle.textContent=tab==="Home"?"See what matters today, then start studying.":tab==="Study Plan"?"Choose a subject, then tick each chapter as you complete it.":tab==="Tasks"?"Keep only the next actions you need to finish.":"Complete the syllabus, revise four times, and be ready for 30 April 2027.";({Home:renderToday,"Study Plan":renderSyllabus,Tasks:renderTasks,Roadmap:renderRoadmap}[tab])();if(tab==="Tasks")view.insertAdjacentHTML("afterbegin",taskCalendarHTML())}

function portableBackupHTML(){return `<section class="portable-backup"><div><span>DATA SAFETY</span><h2>Keep your preparation portable.</h2><p>Export one backup containing progress, tasks, notes, links and checklists. Restore it on a new browser or computer.</p></div><div><button type="button" id="quick-export">↓ Export backup</button><button type="button" id="quick-import">↑ Import backup</button></div></section>`}
