function studyHeatmapHTML(){const now=new Date(),months=[],milestones={"2026-10-31":"Syllabus completion deadline","2026-12-31":"Revision 1 deadline","2027-02-28":"Revision 2 deadline","2027-03-31":"Revision 3 deadline","2027-04-15":"Revision 4 and final PYQ deadline","2027-04-30":"CA Final attempt"};for(let offset=0;offset<16;offset++){const first=new Date(2026,offset,1),days=new Date(2026,offset+1,0).getDate(),cells=[];for(let blank=0;blank<first.getDay();blank++)cells.push('<i class="heat-day blank"></i>');for(let day=1;day<=days;day++){const date=new Date(first.getFullYear(),first.getMonth(),day,12),key=dateKey(date),count=state.topicActivity?.[key]||0,future=date>now,milestone=milestones[key],level=future?0:count===0?0:count===1?1:count<=3?2:count<=5?3:4,activity=`${count} topic${count===1?"":"s"} completed`,tip=milestone?`${date.toLocaleDateString(undefined,{weekday:"short",day:"numeric",month:"long",year:"numeric"})} — ${milestone} · ${activity}`:future?`${date.toLocaleDateString(undefined,{day:"numeric",month:"long",year:"numeric"})} — future date`:`${date.toLocaleDateString(undefined,{weekday:"short",day:"numeric",month:"long",year:"numeric"})} — ${activity}`;cells.push(`<i class="heat-day level-${level} ${future?"future":""} ${key===dateKey(now)?"today":""} ${milestone?"milestone":""}" title="${tip}" aria-label="${tip}">${day}${milestone?'<span class="milestone-dot"></span>':""}</i>`)}months.push(`<section class="heat-month"><h3>${first.toLocaleString(undefined,{month:"short"})} <small>${first.getFullYear()}</small></h3><div class="heat-weekdays">${["S","M","T","W","T","F","S"].map(x=>`<b>${x}</b>`).join("")}</div><div class="heat-month-grid">${cells.join("")}</div></section>`)}return `<section class="activity-card"><div class="activity-head"><div><h2>Study consistency & deadlines</h2><p>Scroll horizontally through April 2027. Purple-ringed dates are preparation milestones.</p></div><div class="calendar-controls"><button type="button" data-calendar-scroll="-1">← Earlier</button><span>2026 → 30 APRIL 2027</span><button type="button" data-calendar-scroll="1">Later →</button></div></div><div class="heat-scroll"><div class="heat-months">${months.join("")}</div></div><div class="heat-legend"><span>0 topics</span>${[0,1,2,3,4].map(n=>`<i class="heat-day level-${n}"></i>`).join("")}<span>6+ topics</span><i class="heat-day milestone"></i><span>Milestone</span></div></section>`}
const frUnitTopics={"Presentation of General Purpose Financial Statements (Ind AS 1, 34 & 7)":["Ind AS 1 — Presentation of Financial Statements","Ind AS 34 — Interim Financial Reporting","Ind AS 7 — Statement of Cash Flows"],"Accounting Policies, Events after Reporting & Fair Value (Ind AS 8, 10 & 113)":["Ind AS 8 — Accounting Policies, Estimates and Errors","Ind AS 10 — Events after the Reporting Period","Ind AS 113 — Fair Value Measurement"],"Assets of Financial Statements (Ind AS 2, 16, 23, 36, 38, 40, 105 & 116)":["Ind AS 2 — Inventories","Ind AS 16 — Property, Plant and Equipment","Ind AS 23 — Borrowing Costs","Ind AS 36 — Impairment of Assets","Ind AS 38 — Intangible Assets","Ind AS 40 — Investment Property","Ind AS 105 — Assets Held for Sale","Ind AS 116 — Leases"],"Liabilities (Ind AS 19 & 37)":["Ind AS 19 — Employee Benefits","Ind AS 37 — Provisions and Contingencies"],"Income Taxes & Foreign Exchange (Ind AS 12 & 21)":["Ind AS 12 — Income Taxes","Ind AS 21 — Foreign Exchange Rates"],"Disclosures (Ind AS 24, 33 & 108)":["Ind AS 24 — Related Party Disclosures","Ind AS 33 — Earnings per Share","Ind AS 108 — Operating Segments"],"Other Ind AS (41, 20 & 102)":["Ind AS 41 — Agriculture","Ind AS 20 — Government Grants","Ind AS 102 — Share-based Payment"],"Financial Instruments (Ind AS 32, 107 & 109)":["Scope and definitions","Classification and measurement","Equity and financial liabilities","Derivatives and embedded derivatives","Recognition and derecognition","Hedge accounting","Financial instrument disclosures"],"Consolidated & Separate Financial Statements (Ind AS 110, 111, 28 & 27)":["Introduction and important definitions","Ind AS 110 — Consolidated Financial Statements","Consolidation procedure for subsidiaries","Ind AS 111 — Joint Arrangements","Ind AS 28 — Associates and Joint Ventures","Ind AS 27 — Separate Financial Statements","Group disclosure requirements"]};
