function topicChecklistHTML(subject,chapter,index){const key=progressKey(subject.code,index),items=chapterTopicNames(subject,chapter),custom=state.customTopics?.[key]||[],saved=state.topicChecks?.[key],chapterDone=!!state.progress[key]?.done,doneCount=items.filter((_,i)=>saved?(saved[i]?.done??saved[i]===true):chapterDone).length+custom.filter(x=>x.done).length,total=items.length+custom.length;return `<section class="chapter-topics"><div class="topic-list-head"><b>${doneCount}/${total} topics complete</b><button type="button" class="create-subtopic">＋ Create subtopic</button></div>${items.map((topic,i)=>{const checked=saved?(saved[i]?.done??saved[i]===true):chapterDone;return `<label class="topic-check-row ${checked?"done":""}"><input type="checkbox" data-topic-check="${i}" ${checked?"checked":""}><span>${esc(topic)}</span></label>`}).join("")}<div class="custom-topic-list">${custom.map(topic=>customTopicHTML(key,topic)).join("")}</div></section>`}
