renderSyllabus=function(){renderSyllabusBase();const tabs=view.querySelector(".paper-tabs"),head=view.querySelector(".paper-head"),chapters=view.querySelector("#chapters"),subject=subjects.find(x=>x.code===paper),chapterRows=[...chapters?.querySelectorAll(".chapter")||[]],count=chapterRows.length;chapterRows.forEach((row,index)=>{const key=progressKey(subject.code,index);row.querySelector(".chapter-main")?.insertAdjacentHTML("afterend",topicChecklistHTML(subject,subject.chapters[index],index));const amount=chapterTopicNames(subject,subject.chapters[index]).length+(state.customTopics?.[key]?.length||0);row.querySelector(".chapter-name small")?.insertAdjacentHTML("beforeend",` · ${amount} topics`)});tabs?.insertAdjacentHTML("afterend",studyHeatmapHTML());if(!chapters)return;chapters.insertAdjacentHTML("beforebegin",`<div class="checklist-heading"><div><h2>Chapter & topic checklist</h2><p>Open a chapter, then tick each topic inside it as you complete it.</p></div><b>${count} chapters</b></div>`);const heading=chapters.previousElementSibling,workspace=document.createElement("div"),main=document.createElement("div"),side=document.createElement("aside");workspace.className="study-workspace";main.className="study-main";side.className="study-side";main.append(heading,chapters);side.append(head);const total=subject.chapters.length,rows=[1,2,3,4].map(n=>{const done=subject.chapters.filter((_,i)=>(state.progress[progressKey(subject.code,i)]?.revisions||0)>=n).length,pct=Math.round(done/total*100);return `<div class="side-progress-row"><span>Revision ${n}</span><div class="progress"><i style="width:${pct}%"></i></div><b>${done}/${total}</b></div>`}).join("");side.insertAdjacentHTML("beforeend",`<section class="side-progress"><h3>${subject.code} revision progress</h3>${rows}</section>`);workspace.append(main,side);view.append(workspace);bindTopicChecks(subject)};
function taskCalendarHTML(){const today=dateKey(),todayItems=(state.tasks||[]).filter(t=>(t.dueDate||today)===today),todayDone=todayItems.filter(t=>t.done).length,todayPct=todayItems.length?Math.round(todayDone/todayItems.length*100):0,pending=state.tasks.filter(t=>!t.done).length,upcoming=state.tasks.filter(t=>!t.done&&(t.dueDate||today)>today).length,overdue=state.tasks.filter(t=>!t.done&&(t.dueDate||today)<today).length,weights={low:1,medium:2,high:3},days=[];for(let offset=29;offset>=0;offset--){const date=new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()-offset);const key=dateKey(date),items=state.tasks.filter(t=>(t.dueDate||(!t.createdAt?today:""))===key),totalWeight=items.reduce((sum,t)=>sum+(weights[t.priority]||1),0),doneWeight=items.filter(t=>t.done).reduce((sum,t)=>sum+(weights[t.priority]||1),0),score=totalWeight?Math.round(doneWeight/totalWeight*100):0,hue=Math.round(score*1.2),light=score===100?Math.max(55,84-Math.min(25,totalWeight*4)):88,label=items.length?`${items.filter(t=>t.done).length}/${items.length} complete · priority score ${score}%`:"No tasks";days.push(`<div class="todo-history-day" title="${date.toLocaleDateString()}: ${label}"><i class="todo-history-circle ${items.length?"scored":"none"}" ${items.length?`style="--score-hue:${hue};--score-light:${light}%"`:""}>${date.getDate()}</i><small>${date.toLocaleString(undefined,{month:"short"})}</small></div>`)}return `<div class="todo-hero"><section class="todo-today"><div class="todo-eyebrow">TODAY'S CHECKLIST</div><div class="todo-date-title">${new Date().toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric"})}</div><p>${todayItems.length?`${todayItems.length-todayDone} task${todayItems.length-todayDone===1?"":"s"} left today`:"Your day is clear — add a task when ready."}</p><div class="todo-progress-line" style="--pct:${todayPct}%"><span></span></div><div class="todo-progress-meta"><span>${todayDone} completed</span><span>${todayPct}%</span></div></section><section class="todo-summary"><div class="todo-summary-item"><b>${pending}</b><span>Pending</span></div><div class="todo-summary-item"><b>${todayItems.length}</b><span>Today</span></div><div class="todo-summary-item"><b>${upcoming}</b><span>Upcoming</span></div><div class="todo-summary-item"><b>${overdue}</b><span>Overdue</span></div></section></div><section class="todo-history"><div class="todo-history-head"><div><h3>Last 30 days</h3><p>Important completed tasks create a stronger green day.</p></div><div class="todo-history-legend"><span><i style="background:#76cc90"></i>Strong</span><span><i style="background:#e5bc4e"></i>Partial</span><span><i style="background:#e06a6a"></i>Unfinished</span><span><i style="background:#e5e7ee"></i>No tasks</span></div></div><div class="todo-history-scroll"><div class="todo-history-days">${days.join("")}</div></div></section>`}

function renderToday(){const all=allChapters(),done=all.filter(x=>state.progress[x.key]?.done).length,pct=Math.round(done/all.length*100);view.innerHTML=`<section class="grid-hero"><article class="mission"><div class="mission-row"><div><span class="kicker">COURSE COMPLETION MISSION</span><h2>Own your complete syllabus.</h2><p>Complete every chapter, then build exam-ready recall through four revision cycles.</p></div><div class="ring" style="--p:${pct}%"><b>${pct}%</b></div></div><div class="stats"><div><small>CHAPTERS MASTERED</small><b>${done} / ${all.length}</b></div><div><small>COMPLETION TARGET</small><b>31 Oct</b></div><div><small>REVISION TARGET</small><b>4 cycles</b></div><div><small>EXAM WINDOW</small><b>2027</b></div></div></article><article class="card deadline"><div class="calendar">31<small>OCT</small></div><div><span class="kicker" style="color:#c77942;background:#fff3ea">NEXT MILESTONE</span><h3>First coverage complete</h3><p>Finish all ${all.length} chapters and first-pass questions.</p><div class="progress"><i style="width:${pct}%;--accent:#dd9964"></i></div><p><b>${done} complete</b> · ${all.length-done} remaining</p></div></article></section><div class="section-title"><div><h2>Your subjects</h2><p>Six papers. One clear path.</p></div><button class="link-btn" id="open-syllabus">View full syllabus →</button></div><section class="subject-grid">${subjects.map(s=>{const count=s.chapters.filter((_,i)=>state.progress[progressKey(s.code,i)]?.done).length,p=Math.round(count/s.chapters.length*100);return `<article class="card subject" data-paper="${s.code}" style="--accent:${s.color}"><span class="code">${s.code}</span><h3>${esc(s.name)}</h3><p>${count} of ${s.chapters.length} chapters mastered</p><div class="progress"><i style="width:${p}%"></i></div><footer><b>${p}%</b><span>Open paper →</span></footer></article>`}).join("")}</section>`;document.querySelector("#open-syllabus").onclick=()=>{tab="Syllabus";render()};document.querySelectorAll("[data-paper]").forEach(el=>el.onclick=()=>{paper=el.dataset.paper;tab="Syllabus";render()})}

function renderSyllabus(){const s=subjects.find(x=>x.code===paper),done=s.chapters.filter((_,i)=>state.progress[progressKey(s.code,i)]?.done).length;view.innerHTML=`<div class="paper-tabs">${subjects.map(x=>`<button data-paper="${x.code}" class="${x.code===paper?"active":""}" style="--accent:${x.color}">${x.code} · ${x.chapters.length}</button>`).join("")}</div><section class="paper-head"><div><h2>${esc(s.name)}</h2><p>ICAI New Scheme · completion and revision tracker</p></div><b>${done}/${s.chapters.length}</b></section><div id="chapters">${s.chapters.map((name,i)=>chapterHTML(s,name,i)).join("")}</div>`;document.querySelectorAll("[data-paper]").forEach(el=>el.onclick=()=>{paper=el.dataset.paper;renderSyllabus()});bindChapters(s)}
function chapterHTML(s,name,i){const key=progressKey(s.code,i),p=state.progress[key]||{},note=p.notesHtml||esc(p.notes||"").replace(/\n/g,"<br>");return `<article class="chapter ${p.done?"done":""}" data-key="${key}" data-index="${i}"><div class="chapter-main"><button class="done-btn">${p.done?"✓":i+1}</button><div class="chapter-name"><b>${esc(name)}</b><small>${p.done?"Mastered":p.revisit?"Flagged to revisit":"Not started"}</small></div><div class="chapter-actions"><button class="flag ${p.revisit?"on":""}">↺ Revisit</button><button class="rev-minus">−</button><strong>${p.revisions||0}</strong><button class="rev-plus">+</button><button class="expand">⌄</button></div></div><div class="chapter-detail"><label class="notes-field">CHAPTER NOTES<div class="rich-editor"><div class="editor-toolbar"><button type="button" data-cmd="bold" title="Bold">B</button><button type="button" data-cmd="italic" title="Italic"><i>I</i></button><button type="button" data-cmd="underline" title="Underline"><u>U</u></button><button type="button" data-block="h3" title="Heading">H</button><button type="button" class="highlight" data-cmd="hiliteColor" data-value="#fff09a" title="Highlight">H</button><button type="button" data-cmd="insertUnorderedList" title="Bullet list">• List</button><button type="button" data-cmd="insertOrderedList" title="Numbered list">1. List</button><button type="button" data-checklist title="Checklist">☐</button><button type="button" data-link title="Add link">🔗</button><button type="button" data-cmd="removeFormat" title="Clear formatting">Tx</button></div><div class="editor-area" contenteditable="true" data-placeholder="Write summaries, formulas, mistakes, mnemonics and revision points…">${safeNote(note)}</div><div class="editor-footer"><div><button type="button" class="save-note">Save note</button><button type="button" class="expand-note">⛶ Expand</button></div><span class="note-status">${p.noteSavedAt?`Saved ${new Date(p.noteSavedAt).toLocaleDateString()}`:"Ready to write"}</span></div></div></label><label class="side-field">YOUTUBE / LECTURE LINK<input class="youtube" value="${esc(p.youtube||"")}" placeholder="https://youtube.com/…"></label><label class="side-field">STUDY DOCUMENT<span class="file-zone">${p.file?`✓ ${esc(p.file)}`:"＋ Choose PDF, image or document"}<input class="file-input" type="file"></span><span class="file-tools">${p.file?`<button class="file-open">Open</button><button class="file-remove">Remove</button>`:""}</span></label></div></article>`}
function bindChapters(s){document.querySelectorAll(".chapter").forEach(row=>{const key=row.dataset.key,editor=row.querySelector(".editor-area"),noteStatus=row.querySelector(".note-status");row.querySelector(".done-btn").onclick=()=>{setProgress(key,{done:!state.progress[key]?.done});renderSyllabus()};row.querySelector(".flag").onclick=()=>{setProgress(key,{revisit:!state.progress[key]?.revisit});renderSyllabus()};row.querySelector(".rev-minus").onclick=()=>{setProgress(key,{revisions:Math.max(0,(state.progress[key]?.revisions||0)-1)});renderSyllabus()};row.querySelector(".rev-plus").onclick=()=>{setProgress(key,{revisions:(state.progress[key]?.revisions||0)+1});renderSyllabus()};row.querySelector(".expand").onclick=()=>row.classList.toggle("open");editor.oninput=()=>noteStatus.textContent="Unsaved changes";row.querySelectorAll("[data-cmd]").forEach(button=>button.onclick=()=>{editor.focus();document.execCommand(button.dataset.cmd,false,button.dataset.value||null);noteStatus.textContent="Unsaved changes"});row.querySelector("[data-block]").onclick=()=>{editor.focus();document.execCommand("formatBlock",false,"h3");noteStatus.textContent="Unsaved changes"};row.querySelector("[data-checklist]").onclick=()=>{editor.focus();document.execCommand("insertText",false,"☐ ");noteStatus.textContent="Unsaved changes"};row.querySelector("[data-link]").onclick=()=>{const url=prompt("Paste a web link");if(url&&/^https?:\/\//i.test(url)){editor.focus();document.execCommand("createLink",false,url);noteStatus.textContent="Unsaved changes"}};row.querySelector(".save-note").onclick=()=>{const now=new Date().toISOString();setProgress(key,{notesHtml:safeNote(editor.innerHTML),notes:"",noteSavedAt:now});noteStatus.textContent="Saved just now";toast("Note saved and queued for sync")};row.querySelector(".youtube").onchange=e=>setProgress(key,{youtube:e.target.value});row.querySelector(".file-input").onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024)return alert("Please keep each document below 50 MB.");try{await putDocument(key,file);setProgress(key,{file:file.name});renderSyllabus();toast("Document saved for offline use")}catch{alert("The document could not be saved. Check available browser storage and try again.")}};row.querySelector(".file-open")?.addEventListener("click",async()=>{const d=await getDocument(key);if(!d)return alert("This document is no longer available in this browser.");const url=URL.createObjectURL(d.blob),win=open(url,"_blank");if(!win)alert("Please allow pop-ups to open this document.");setTimeout(()=>URL.revokeObjectURL(url),60000)});row.querySelector(".file-remove")?.addEventListener("click",async()=>{await deleteDocument(key);setProgress(key,{file:""});renderSyllabus()})})}

function renderRevision(){const all=allChapters(),queue=all.filter(x=>state.progress[x.key]?.revisit);view.innerHTML=`<div class="intro"><div><h2>Revision cockpit</h2><p>Active recall, spaced repetition and timed practice.</p></div><span>${queue.length} to revisit</span></div><section class="subject-grid">${[1,2,3,4].map(n=>{const count=all.filter(x=>(state.progress[x.key]?.revisions||0)>=n).length;return `<article class="card"><span class="code">R${n}</span><h3>${["7-day recall","21-day reinforcement","60-day retention","Final exam sprint"][n-1]}</h3><p>${count} / ${all.length} chapters</p><div class="progress"><i style="width:${count/all.length*100}%"></i></div></article>`}).join("")}</section><div class="section-title"><div><h2>Revisit queue</h2><p>Every difficult topic in one place.</p></div></div>${queue.length?queue.map(x=>`<article class="card" style="margin-bottom:7px"><b>${x.s.code} · ${esc(x.chapter)}</b></article>`).join(""):`<div class="card empty">Flag difficult chapters with “Revisit” and they will appear here.</div>`}`}

function renderTasks(){const today=dateKey(),groups={};state.tasks.forEach(task=>{const key=task.dueDate||today;(groups[key]||=[]).push(task)});const cards=Object.entries(groups).sort(([a],[b])=>a.localeCompare(b)).map(([date,tasks])=>{const parsed=new Date(`${date}T12:00:00`),done=tasks.filter(t=>t.done).length,label=date===today?"Today":date<today?"Earlier":"Upcoming";return `<section class="todo-date-card ${date===today?"is-today":""}"><div class="todo-card-head"><div class="todo-calendar"><small>${parsed.toLocaleString(undefined,{month:"short"})}</small><b>${parsed.getDate()}</b></div><div class="todo-card-title"><h3>${label}</h3><p>${parsed.toLocaleDateString(undefined,{weekday:"long",year:"numeric",month:"long",day:"numeric"})}</p></div><span class="todo-card-count">${done}/${tasks.length}</span></div><div class="todo-items">${tasks.sort((a,b)=>({high:0,medium:1,low:2}[a.priority||"low"]-({high:0,medium:1,low:2}[b.priority||"low"]))).map(taskHTML).join("")}</div></section>`}).join("");view.innerHTML=`<div class="intro"><div><h2>Plan your work</h2><p>Add a dated task and choose how important it is.</p></div><span>${state.tasks.filter(t=>t.done).length}/${state.tasks.length} done</span></div><form class="task-form task-form-wide"><input id="task-text" required placeholder="What needs to get done?"><select id="task-subject" aria-label="Subject">${subjects.map(s=>`<option>${s.code}</option>`).join("")}<option value="Other">Other / Personal</option></select><select id="task-priority" aria-label="Priority"><option value="low">Low priority</option><option value="medium" selected>Medium priority</option><option value="high">High priority</option></select><input id="task-date" type="date" value="${today}" aria-label="Task date"><button class="primary">Add task</button></form><div class="todo-date-grid">${cards||'<div class="card empty">No tasks yet. Add your first task above.</div>'}</div>`;document.querySelector(".task-form").onsubmit=e=>{e.preventDefault();const dueDate=document.querySelector("#task-date").value||today;state.tasks.push({id:Date.now(),text:document.querySelector("#task-text").value.trim(),subject:document.querySelector("#task-subject").value,priority:document.querySelector("#task-priority").value,dueDate,createdAt:today,due:dueDate===today?"Today":"Upcoming",done:false});saveState();render()};document.querySelectorAll("[data-task]").forEach(b=>b.onclick=()=>{const t=state.tasks.find(x=>x.id===Number(b.dataset.task));t.done=!t.done;t.completedAt=t.done?today:"";t.priority=t.priority||"low";t.dueDate=t.dueDate||today;saveState();render()})}
function taskHTML(t){const priority=t.priority||"low",due=t.dueDate?new Date(`${t.dueDate}T12:00:00`).toLocaleDateString(undefined,{day:"numeric",month:"short"}):t.due;return `<article class="task priority-${priority}"><button data-task="${t.id}" aria-label="Mark task ${t.done?"incomplete":"complete"}">${t.done?"✓":""}</button><div><b>${esc(t.text)}</b><small>${t.subject} · ${due||"Today"} · <span>${priority} priority</span></small></div></article>`}

const roadmapPhases=[
 {id:"coverage",window:"NOW → 31 OCT 2026",title:"Complete 100% of the syllabus",description:"Build the full base before starting revision cycles.",items:["Finish Financial Reporting","Finish Advanced Financial Management","Finish Advanced Auditing","Finish Direct Tax Laws","Finish Indirect Tax Laws","Finish Integrated Business Solutions","Complete ICAI module illustrations and questions","Prepare compact chapter-wise notes"]},
 {id:"revision1",window:"NOV–DEC 2026",title:"Revision 1 · Rebuild every concept",description:"Return to every chapter while the first study is still fresh.",items:["Revise all six papers once","Solve chapter-wise previous-year questions","Start a mistake and difficult-question book","Update notes with weak areas and amendments"]},
 {id:"revision2",window:"JAN–FEB 2027",title:"Revision 2 · Improve recall and speed",description:"Move from understanding to timed application.",items:["Complete the second revision of all papers","Attempt timed sectional tests","Redo every marked PYQ and mistake-book question","Practise IBS case-study navigation"]},
 {id:"revision3",window:"MARCH 2027",title:"Revision 3 · Enter exam conditions",description:"Practise complete papers and correct weaknesses quickly.",items:["Complete the third revision of all papers","Solve applicable RTPs and MTPs","Attempt full-length previous-year papers","Analyse every mock and fix recurring errors"]},
 {id:"revision4",window:"1–15 APR 2027",title:"Revision 4 · Final exam consolidation",description:"Turn the whole course into fast, reliable recall.",items:["Complete the fourth revision of all papers","Finish the final PYQ, RTP and MTP cycle","Revise amendments, summary notes and formulas","Attempt final full-length mocks under exam timing"]},
 {id:"exam",window:"30 APRIL 2027",title:"CA Final attempt · Execute calmly",description:"Protect energy, recall and confidence during the attempt.",items:["Keep admit card and exam logistics ready","Use only final notes and the mistake book","Follow the paper-wise last-day revision plan","Complete the 30 April attempt with calm execution"]}
];
function renderRoadmap(){state.roadmapChecks=state.roadmapChecks||{};const all=allChapters(),syllabusDone=all.filter(x=>state.progress[x.key]?.done).length,total=roadmapPhases.reduce((n,p)=>n+p.items.length,0),checked=roadmapPhases.reduce((n,p)=>n+p.items.filter((_,i)=>state.roadmapChecks[`${p.id}-${i}`]).length,0),pct=Math.round(checked/total*100),firstIncomplete=roadmapPhases.findIndex(p=>p.items.some((_,i)=>!state.roadmapChecks[`${p.id}-${i}`]));view.innerHTML=`<section class="roadmap-hero"><div><span class="roadmap-kicker">30 APRIL 2027 · 100% PREPARATION PLAN</span><h2>One syllabus. Four revisions. One confident attempt.</h2><p>Tick each milestone as you complete it. Your syllabus progress is linked live from Study Plan.</p><div class="roadmap-targets"><span><b>31 Oct 2026</b>Syllabus complete</span><span><b>By 15 April</b>4 revisions + PYQs</span><span><b>30 April 2027</b>CA Final attempt</span></div></div><div class="roadmap-score"><div class="roadmap-ring" style="--roadmap-p:${pct}%"><strong>${pct}%</strong><small>ROADMAP</small></div><b>${checked} of ${total} milestones</b></div></section><section class="roadmap-live"><div><span>LIVE SYLLABUS COVERAGE</span><b>${syllabusDone} / ${all.length} chapters</b></div><div class="roadmap-progress"><i style="width:${Math.round(syllabusDone/all.length*100)}%"></i></div><button id="roadmap-study">Open Study Plan →</button></section><section class="roadmap-timeline">${roadmapPhases.map((phase,phaseIndex)=>{const phaseDone=phase.items.filter((_,i)=>state.roadmapChecks[`${phase.id}-${i}`]).length,isComplete=phaseDone===phase.items.length,isCurrent=phaseIndex===(firstIncomplete<0?roadmapPhases.length-1:firstIncomplete);return `<article class="roadmap-phase ${isComplete?"complete":""} ${isCurrent?"current":""}"><div class="roadmap-marker"><span>${isComplete?"✓":phaseIndex+1}</span></div><div class="roadmap-phase-card"><header><div><small>${phase.window}</small><h3>${phase.title}</h3><p>${phase.description}</p></div><b>${phaseDone}/${phase.items.length}</b></header><div class="roadmap-checklist">${phase.items.map((item,itemIndex)=>{const key=`${phase.id}-${itemIndex}`,done=!!state.roadmapChecks[key];return `<label class="roadmap-check ${done?"done":""}"><input type="checkbox" data-roadmap-check="${key}" ${done?"checked":""}><span>${esc(item)}</span></label>`}).join("")}</div></div></article>`}).join("")}</section>`;document.querySelector("#roadmap-study").onclick=()=>{tab="Study Plan";render()};document.querySelectorAll("[data-roadmap-check]").forEach(box=>box.onchange=()=>{state.roadmapChecks[box.dataset.roadmapCheck]=box.checked;saveState();renderRoadmap()})}

function renderStrategy(){const phases=[["NOW → 31 OCT 2026","Complete 100% syllabus","Classes, ICAI modules and first-pass questions."],["NOV–DEC 2026","Revision 1 + question bank","Chapter-wise PYQs, RTPs and a mistake book."],["JAN–FEB 2027","Revision 2 + sectional tests","Timed writing, MCQs and IBS case practice."],["MARCH 2027","Revision 3 + full mocks","Strict exam simulation and rapid correction."],["1–15 APRIL 2027","Revision 4 + calm execution","Summary notes, amendments and final mocks before 30 April."]];view.innerHTML=`<div class="intro"><div><h2>Your 100% preparation roadmap</h2><p>Coverage creates confidence. Revision creates rank.</p></div></div><section class="roadmap">${phases.map((x,i)=>`<article class="card"><span class="step">${i+1}</span><div><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div></article>`).join("")}</section><div class="section-title"><div><h2>Eligibility & becoming a CA</h2><p>Verify your exact status in ICAI SSP.</p></div></div><section class="qualification">${qualification.map((q,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[i]?"checked":""}> ${esc(q)}</label>`).join("")}</section>`;document.querySelectorAll("[data-check]").forEach(c=>c.onchange=()=>{state.checks[c.dataset.check]=c.checked;saveState()})}

const resources=[["ICAI Final syllabus & modules","https://www.icai.org/post/final-nset","Official study material for all six papers"],["BoS Knowledge Portal","https://boslive.icai.org/education_content","Lectures, RTPs, MTPs and suggested answers"],["Digital Learning Campus (SPOM)","https://lms.icai.org/login","Complete applicable Sets A–D"],["ICAI Exam Services","https://eservices.icai.org/","Exam forms and official services"],["ICAI BoS YouTube","https://www.youtube.com/@ICAI_CA_Tube","Official classes and revision sessions"]];
function renderResources(){view.innerHTML=`<section class="backup"><div><span class="kicker">PORTABLE DATA VAULT</span><h2>Take everything with you.</h2><p>The full backup includes progress, revisions, tasks, notes, checks and all uploaded documents.</p></div><div class="backup-actions"><button id="export">↓ Export full backup</button><button class="secondary" id="import">↑ Import & restore</button></div></section><div class="intro"><div><h2>Trusted resource library</h2><p>Official-first. Attempt-specific.</p></div></div><section class="resource-grid">${resources.map(r=>`<a class="card" href="${r[1]}" target="_blank" rel="noreferrer"><h3>${r[0]}</h3><p>${r[2]}</p><small>Open resource ↗</small></a>`).join("")}</section>`;document.querySelector("#export").onclick=exportBackup;document.querySelector("#import").onclick=()=>document.querySelector("#restore-input").click()}

document.querySelector("#focus-btn").onclick=()=>{if(timerId){clearInterval(timerId);timerId=null;document.querySelector("#focus-btn").textContent=`▶ ${formatTimer(timer)}`;return}timerId=setInterval(()=>{timer++;document.querySelector("#focus-btn").textContent=`Ⅱ ${formatTimer(timer)}`},1000)};
function formatTimer(seconds){return `${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`}

const DB_NAME="ca-finals-vanilla-files",STORE="documents";
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore(STORE);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function putDocument(key,file){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).put({name:file.name,type:file.type,size:file.size,lastModified:file.lastModified||Date.now(),blob:file},key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function getDocument(key){const db=await openDb();return new Promise((resolve,reject)=>{const req=db.transaction(STORE).objectStore(STORE).get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function deleteDocument(key){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function listDocuments(){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE),store=tx.objectStore(STORE),keys=store.getAllKeys(),values=store.getAll();tx.oncomplete=()=>resolve(keys.result.map((k,i)=>[k,values.result[i]]));tx.onerror=()=>reject(tx.error)})}
function blobToBase64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(",")[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
function base64ToBlob(data,type){const raw=atob(data),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type})}
