function coachThoughtCount(mood){return {celebrating:4,happy:5,angry:7,frustrated:6,worried:4}[mood]||1}
function timeGreeting(date=new Date()){const hour=date.getHours();return hour<12?"Good morning":hour<17?"Good afternoon":"Good evening"}
function studyCoachData(){const s=prepSnapshot(),todayDone=completedTopicsOn(),overdue=(state.tasks||[]).filter(task=>!task.done&&task.dueDate&&task.dueDate<dateKey()).length,syllabusDeadline=new Date(2026,9,31,12),today=new Date();today.setHours(12,0,0,0);const syllabusDays=Math.max(1,Math.ceil((syllabusDeadline-today)/86400000)),pace=Math.max(1,Math.ceil(s.topicsRemaining/(today<=syllabusDeadline?syllabusDays:Math.max(1,s.days)))),mood=todayDone>=6?"celebrating":todayDone>0?"happy":overdue>=3?"frustrated":pace>=5?"angry":"worried",messages={celebrating:[`I love you, Sweety! ${todayDone} topics today — I’m jumping with happiness and I’m so proud of you!`,`Six-plus topics complete! I love you and I love seeing you fight for your CA dream.`,`This consistency is powerful, Sweety. I love you — keep growing, future CA!`,`What a day! ${todayDone} topics completed. You are making our dream feel real, and I’m incredibly proud of you.`],happy:[`Sweety, you completed ${todayDone} topic${todayDone===1?"":"s"} today — daily progress becomes lasting growth.`,`I’m so happy to see your progress. Maintain this consistency and keep preparing for your CA first attempt.`,`I believe in you, Sweety. One honest study session at a time, you can become a CA.`,`We are moving toward your dream. Today’s work makes me proud of you.`,`I care about you and your dream. Keep this momentum steady and sustainable.`],angry:[`Aukat hai to karke dikha! Ek topic abhi complete karo.`,`Dum hai to padhna! CA ka sapna daily action maangta hai.`,`Sweety, nothing is completed today and the required pace is high. Please start one manageable topic now.`,`${s.topicsRemaining} topics remain; the October target needs about ${pace} topics a day. I care about your dream, so I won’t pretend delay is okay.`,`Your first-attempt CA dream needs action today. Pick one topic and finish it — I’m with you.`,`I believe you can become a CA, but belief must be supported by consistent work.`,`Your dream matters to both of us. Give it one focused, distraction-free session now.`],frustrated:[`Aukat hai to karke dikha, Sweety — excuses ko side rakho aur ek priority task finish karo!`,`Dum hai to padhna! Aaj ka din abhi bhi recover ho sakta hai.`,`${overdue} tasks are overdue and nothing is completed today. Let’s clear one small task first and regain control.`,`I’m frustrated by the delay, never by you. Reset the plan and complete the next realistic action.`,`Consistency has slipped, but the day is still recoverable. I know you can change its direction.`,`Do not try to fix everything at once, Sweety. I’m beside you — finish one priority task, then the next.`],worried:[`Sweety, no topic is completed today yet. I’m worried about consistency because I care about your CA dream.`,`There are ${s.days} days until the exam. I want to see you become a CA, and a calm daily routine will help.`,`I believe in you, but today still needs one completed topic. Let’s make it happen.`,`Progress does not need to be perfect; it needs to continue. I’m always cheering for you.`]};return {...s,todayDone,overdue,syllabusDays,pace,mood,message:messages[mood][coachQuoteIndex%messages[mood].length]}}
function coachHTML(){const coach=studyCoachData(),labels={celebrating:"I’m jumping with joy!",happy:"Very happy with your progress",angry:"I care, so we need action",frustrated:"Let’s reset the day together",worried:"Concerned because your dream matters"};return `<section class="study-coach ${coach.mood}" aria-live="polite"><button type="button" class="coach-trigger" aria-label="Hear another thought from Mitesh"><span class="coach-bot" aria-hidden="true"><i class="coach-antenna"></i><span class="coach-face"><i class="coach-brow left"></i><i class="coach-brow right"></i><i class="coach-eye left"></i><i class="coach-eye right"></i><i class="coach-mouth"></i></span><span class="coach-body"><i></i></span></span><strong class="coach-name">Mitesh</strong></button><div class="coach-copy" role="status"><span class="coach-kicker">MITESH · ${labels[coach.mood]}</span><h2>${coach.message}</h2><p>${coach.todayDone} completed today · ${coach.topicsRemaining} topics remaining</p><p><b>${coach.syllabusDays} days</b> to 31 October · <b>${coach.days} days</b> to 30 April</p><small>Click Mitesh for another thought</small></div></section>`}
