function startCoachIntervention(coach){coachInterventionPending=true;coach.classList.add("settled","coach-rage-run");setTimeout(()=>{if(!coach.isConnected)return;const copy=coach.querySelector(".coach-copy");copy.querySelector(".coach-kicker").textContent="MITESH · BAS, AB STUDY TIME";copy.querySelector("h2").textContent="Chal ab padh! 📚";copy.querySelectorAll("p,small").forEach(item=>item.hidden=true);coach.classList.remove("coach-rage-run");coach.classList.add("coach-intervention","speaking");setTimeout(()=>{if(!coach.isConnected)return;coachQuoteIndex=0;coachThoughtsExhausted=false;coachInterventionPending=false;coachLastThoughtEndsAt=0;const fresh=document.createElement("div");fresh.innerHTML=coachHTML();copy.innerHTML=fresh.querySelector(".coach-copy").innerHTML;coach.classList.remove("coach-intervention","speaking")},2100)},800)}
document.addEventListener("click",event=>{const button=event.target.closest?.(".coach-trigger");if(!button||coachInterventionPending)return;const coach=button.closest(".study-coach");if(coachThoughtsExhausted){startCoachIntervention(coach);return}const current=studyCoachData(),lastThoughtIndex=coachThoughtCount(current.mood)-1;coachQuoteIndex++;const reachedLast=coachQuoteIndex>=lastThoughtIndex,holder=document.createElement("div");holder.innerHTML=coachHTML();const next=holder.firstElementChild;next.classList.add("settled","speaking","reacting");if(reachedLast){coachThoughtsExhausted=true;coachLastThoughtEndsAt=Date.now()+2800;const hint=next.querySelector(".coach-copy small");if(hint)hint.textContent="Last thought — click Mitesh once more"}coach.replaceWith(next);setTimeout(()=>next.isConnected&&next.classList.remove("reacting"),700);setTimeout(()=>next.isConnected&&next.classList.remove("speaking"),2800)},true);
