document.addEventListener("click",event=>{const button=event.target.closest?.(".save-resource-link");if(!button||button.closest(".resource-link-form"))return;event.preventDefault();event.stopImmediatePropagation();const chapter=button.closest(".chapter"),input=chapter.querySelector(".youtube"),value=input.value.trim();if(value&&!/^https?:\/\//i.test(value)){toast("Enter a complete http or https resource link");return}setProgress(chapter.dataset.key,{youtube:value,resourceLink:value,resourceSavedAt:new Date().toISOString()});button.classList.remove("unsaved");button.textContent="Saved ✓";setTimeout(()=>button.textContent="Save link",1600);toast("Resource link saved")},true);
document.addEventListener("click",event=>{const add=event.target.closest?.(".add-resource-link"),cancel=event.target.closest?.(".cancel-resource-link"),save=event.target.closest?.(".resource-link-form .save-resource-link"),remove=event.target.closest?.(".remove-resource-link");if(!add&&!cancel&&!save&&!remove)return;event.preventDefault();event.stopImmediatePropagation();const label=(add||cancel||save||remove).closest(".resource-field"),chapter=label.closest(".chapter"),key=chapter.dataset.key,p=state.progress[key]||{},links=[...(p.resourceLinks||[]),...(p.youtube?[p.youtube]:[])].filter((link,index,list)=>link&&list.indexOf(link)===index);if(add){add.hidden=true;label.querySelector(".resource-link-form").hidden=false;label.querySelector(".resource-link-draft").focus();return}if(cancel){renderResourceField(label);return}if(remove){links.splice(Number(remove.dataset.linkIndex),1);setProgress(key,{resourceLinks:links,youtube:"",resourceLink:""});renderResourceField(label);toast("Resource link removed");return}const input=label.querySelector(".resource-link-draft"),value=input.value.trim();if(!/^https?:\/\//i.test(value)){toast("Enter a complete http or https resource link");return}if(!links.includes(value))links.push(value);setProgress(key,{resourceLinks:links,youtube:"",resourceLink:"",resourceSavedAt:new Date().toISOString()});renderResourceField(label);toast("Resource link saved")},true);
