document.addEventListener("click",event=>{const edit=event.target.closest?.(".builtin-topic-edit"),remove=event.target.closest?.(".builtin-topic-delete");if(!edit&&!remove)return;event.preventDefault();event.stopImmediatePropagation();const button=edit||remove,row=button.closest(".chapter"),key=row.dataset.key,index=Number(button.dataset.topicIndex),subject=subjects.find(item=>item.code===paper),items=chapterTopicNames(subject,subject.chapters[Number(row.dataset.index)]),current=state.topicOverrides?.[key]?.[index]?.name||items[index];state.topicOverrides[key]=state.topicOverrides[key]||{};if(edit){openTextModal({title:"Edit topic name",placeholder:"Topic name",action:"Save",onSubmit:name=>{state.topicOverrides[key][index]={...(state.topicOverrides[key][index]||{}),name};saveState();renderSyllabus();setTimeout(()=>document.querySelector(`[data-key="${key}"]`)?.classList.add("open"),0)}})}else if(confirm(`Delete “${current}”? This cannot be undone.`)){const check=state.topicChecks?.[key]?.[index];if(check?.done&&check.completedAt)state.topicActivity[check.completedAt]=Math.max(0,(state.topicActivity[check.completedAt]||0)-1);state.topicOverrides[key][index]={...(state.topicOverrides[key][index]||{}),deleted:true};if(state.topicChecks?.[key]?.[index])state.topicChecks[key][index].done=false;updateChapterFromTopics(key,items);saveState();renderSyllabus();setTimeout(()=>document.querySelector(`[data-key="${key}"]`)?.classList.add("open"),0)}},true);
document.addEventListener("click",event=>{const button=event.target.closest?.(".created-topic-edit");if(!button)return;event.preventDefault();event.stopImmediatePropagation();const card=button.closest(".custom-topic"),row=button.closest(".chapter"),key=row.dataset.key,topic=state.customTopics?.[key]?.find(item=>String(item.id)===card.dataset.customTopic);if(!topic)return;openTextModal({title:"Edit topic name",placeholder:"Topic name",action:"Save",onSubmit:name=>{topic.name=name;saveState();renderSyllabus();setTimeout(()=>document.querySelector(`[data-key="${key}"]`)?.classList.add("open"),0)}})},true);
prepSnapshot=function(){const today=new Date();today.setHours(12,0,0,0);const exam=new Date(2027,3,30,12),days=Math.max(0,Math.ceil((exam-today)/86400000)),chapters=allChapters(),chaptersDone=chapters.filter(item=>state.progress[item.key]?.done).length;let topicsTotal=0,topicsDone=0;chapters.forEach(item=>{const builtIn=chapterTopicNames(item.s,item.chapter),saved=state.topicChecks?.[item.key],chapterDone=!!state.progress[item.key]?.done,overrides=state.topicOverrides?.[item.key]||{},active=builtIn.map((_,i)=>i).filter(i=>!overrides[i]?.deleted),custom=state.customTopics?.[item.key]||[];topicsTotal+=active.length+custom.length;topicsDone+=active.filter(i=>saved?(saved[i]?.done??saved[i]===true):chapterDone).length+custom.filter(topic=>topic.done).length});return {days,chaptersDone,chaptersTotal:chapters.length,chaptersRemaining:chapters.length-chaptersDone,topicsDone,topicsTotal,topicsRemaining:topicsTotal-topicsDone,topicPct:topicsTotal?Math.round(topicsDone/topicsTotal*100):0}};
taskHTML=function(t){const priority=t.priority||"low",due=t.dueDate?new Date(`${t.dueDate}T12:00:00`).toLocaleDateString(undefined,{day:"numeric",month:"short"}):t.due;return `<article class="task priority-${priority} ${t.done?"done":""}"><button data-task="${t.id}" aria-label="Mark task ${t.done?"incomplete":"complete"}">${t.done?"✓":""}</button><div><b>${esc(t.text)}</b><small>${t.subject} · ${due||"Today"} · <span>${priority} priority</span></small></div><button type="button" class="delete-task" data-task-delete="${t.id}" aria-label="Delete task">×</button></article>`};
